import{_ as t,o as a,c as r,ah as s}from"./chunks/framework.BsNNkeaH.js";const g=JSON.parse('{"title":"Dashboard","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/guide/admin/tableau-de-bord.md","filePath":"src/en/guide/admin/tableau-de-bord.md"}'),o={name:"en/guide/admin/tableau-de-bord.md"};function n(i,e,d,h,l,c){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="dashboard" tabindex="-1">Dashboard <a class="header-anchor" href="#dashboard" aria-label="Permalink to &quot;Dashboard&quot;">​</a></h1><p>The dashboard is the landing page for every signed-in account, but what it shows depends on your role. For an administrator it shows:</p><ul><li>the <strong>To do</strong> block, gathering everything awaiting your decision: applications, site transfers, absence justifications, expenses to approve, leave requests and staff transfers;</li><li>the <strong>Overdue installments</strong> block, listing the families behind on their payment plan (see <a href="/en/guide/prise-en-main.html#overdue-installments">Getting started</a>);</li><li>the <strong>management overview</strong>: the school&#39;s figures as of the moment you open the page.</li></ul><p>That overview is a module in its own right. If it hasn&#39;t been licensed for your school, you still land on the dashboard — just without the indicators described below.</p><h2 id="what-the-figures-cover" tabindex="-1">What the figures cover <a class="header-anchor" href="#what-the-figures-cover" aria-label="Permalink to &quot;What the figures cover&quot;">​</a></h2><p>Every indicator is read for the <strong>current academic year</strong> — the one marked as current in <a href="/en/guide/admin/structure-etablissement.html">School structure</a>.</p><p>If no year is marked as current, the dashboard says so instead of showing figures, with a <strong>Set the current year</strong> button leading to the right screen: nothing can be computed until the reference year is set. That&#39;s the first thing to check if the page looks empty at the start of a term.</p><h2 id="the-indicators" tabindex="-1">The indicators <a class="header-anchor" href="#the-indicators" aria-label="Permalink to &quot;The indicators&quot;">​</a></h2><p>The indicators are grouped into two blocks, <strong>Schooling</strong> and <strong>Finances</strong>.</p><table tabindex="0"><thead><tr><th>Indicator</th><th>What it measures</th></tr></thead><tbody><tr><td>Enrolled students</td><td>Students actually enrolled for the current year</td></tr><tr><td>Average results</td><td>The school&#39;s overall average</td></tr><tr><td>Absence rate</td><td>Absences as a share of the attendance actually recorded</td></tr><tr><td>Boarding occupancy</td><td>Assigned beds against existing beds. Blank — not 0% — for a site with no beds at all</td></tr><tr><td>Amount due</td><td>Total billed to families for the year</td></tr><tr><td>Amount collected</td><td>What has actually been paid</td></tr><tr><td>Recovery rate</td><td>Collected against due</td></tr><tr><td>Amount disbursed</td><td>The school&#39;s approved expenses</td></tr><tr><td>Net cash flow</td><td>Collected minus disbursed</td></tr></tbody></table><p>Two points that prevent misreadings:</p><ul><li>Only <strong>confirmed</strong> payments feed the collected amount. A mobile money payment that was started but never confirmed by the operator doesn&#39;t appear there, and so never inflates the recovery rate.</li><li>The disbursed amount only counts <strong>approved</strong> expenses — an expense still awaiting approval isn&#39;t cash out yet. See <a href="/en/guide/caissier/depenses.html">Expenses</a>.</li></ul><h2 id="reading-the-figures-site-by-site" tabindex="-1">Reading the figures site by site <a class="header-anchor" href="#reading-the-figures-site-by-site" aria-label="Permalink to &quot;Reading the figures site by site&quot;">​</a></h2><p>When the school has several sites, the <strong>By site</strong> block below the indicators repeats the same measures for each of them, so two campuses can be compared without leaving the page. With a single site the block isn&#39;t shown: it would repeat the figures above.</p><p>On a phone this table renders as one card per site rather than columns, to stay readable.</p><h2 id="exporting-the-figures" tabindex="-1">Exporting the figures <a class="header-anchor" href="#exporting-the-figures" aria-label="Permalink to &quot;Exporting the figures&quot;">​</a></h2><p>The <strong>Export spreadsheet</strong> button downloads every indicator, broken down by site, as a spreadsheet file. That&#39;s the format to use for a board meeting or a monthly report: the exported figures are exactly those on screen at the time of the export.</p>',17)])])}const p=t(o,[["render",n]]);export{g as __pageData,p as default};
